waiting-card button{min-height:40px;border:1px solid var(--gn-border);border-radius:999px;background:#fffef9;color:var(--gn-green-dark);padding:0 17px;font:inherit;cursor:pointer}.steps-card{padding:18px}.steps-card h2{margin:0 0 13px;color:var(--gn-text);font-size:17px}.steps-card ol{display:grid;gap:12px;margin:0;padding:0;list-style:none}.steps-card li{display:grid;grid-template-columns:27px 1fr;gap:9px;align-items:start}.steps-card li b{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:#edf0e8;color:var(--gn-subtext);font-size:12px}.steps-card li.done b{background:var(--gn-green);color:#fff}.steps-card span{display:grid;gap:2px}.steps-card strong{color:var(--gn-text);font-size:14px}.steps-card small{color:var(--gn-subtext);font-size:12px;line-height:1.5}.soft-tip{display:flex;gap:10px;align-items:center;padding:13px 15px;color:var(--gn-green-dark);background:#f3f5e9;border-radius:17px}.soft-tip span{font-size:21px}.soft-tip p{margin:0;font-size:13px;line-height:1.55}.error-note{margin:0;color:var(--gn-danger);text-align:center}
